using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with default reflection-based metadata
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1. Strongly-typed metadata: GetTypeInfo returns JsonTypeInfo,
//    but JsonTypeInfo<T> derives from it, so a cast gives you the generic form.
JsonTypeInfo<Person> typedInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Got JsonTypeInfo<Person> — type: {typedInfo.Type.Name}");
Console.WriteLine($"  Properties: {string.Join(", ", typedInfo.Properties.Select(p => p.Name))}");

// 2. Probe without throwing — TryGetTypeInfo (added in .NET 9).
//    Returns false instead of throwing when metadata isn't available.
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
{
    Console.WriteLine($"\nTryGetTypeInfo(Person) succeeded — {info!.Type.Name}");
}

// Now try a type the resolver can't handle (an open generic).
// GetTypeInfo would throw; TryGetTypeInfo just returns false.
if (options.TryGetTypeInfo(typeof(List<>), out _))
{
    Console.WriteLine("Unexpectedly resolved List<>");
}
else
{
    Console.WriteLine("\nTryGetTypeInfo(List<>) returned false — no exception thrown.");
}

record Person(string FirstName, string LastName, int Age);

